script:
// Use native Desk routes and dialogs; this block never writes business data.
(() => {
    const ownWidget = root_element.host.closest(".custom-block-widget-box");
    if (ownWidget) {
        Object.assign(ownWidget.style, { padding: "0", background: "transparent", border: "0", boxShadow: "none" });
    }

    // Recover existing Desk sessions even when their icon script is cached.
    function ensureTheme() {
        if (frappe.restaurant_theme_ready) return frappe.restaurant_theme_ready;
        const styleUrl = "/assets/restaurant/css/restaurant_theme.css?v=20261105.4";
        const scriptUrl = "/assets/restaurant/js/restaurant_theme.js?v=20261105.4";
        const styleReady = new Promise((resolve, reject) => {
            let link = [...document.querySelectorAll('link[rel="stylesheet"]')].find(node => node.href === new URL(styleUrl, location.href).href);
            if (link?.sheet) return resolve();
            if (link) { link.remove(); link = null; }
            if (!link) {
                link = document.createElement("link");
                link.rel = "stylesheet";
                link.href = styleUrl;
            }
            link.addEventListener("load", resolve, { once: true });
            link.addEventListener("error", () => {
                link.remove();
                reject(new Error("Restaurant theme stylesheet failed to load"));
            }, { once: true });
            if (!link.isConnected) document.head.appendChild(link);
        });
        const scriptReady = new Promise((resolve, reject) => {
            if (frappe.restaurant_theme) return resolve();
            const script = document.createElement("script");
            script.src = scriptUrl;
            script.addEventListener("load", resolve, { once: true });
            script.addEventListener("error", () => {
                script.remove();
                reject(new Error("Restaurant theme script failed to load"));
            }, { once: true });
            document.head.appendChild(script);
        });
        const ready = Promise.all([styleReady, scriptReady]).then(() => {
            if (!frappe.restaurant_theme) throw new Error("Restaurant theme did not initialize");
            frappe.restaurant_theme.refresh();
        });
        frappe.restaurant_theme_ready = ready;
        ready.catch(error => {
            delete frappe.restaurant_theme_ready;
            console.error("Restaurant theme assets failed to load", error);
        });
        return ready;
    }
    ensureTheme();

    const routes = {
        pos: { route: ["restaurant-pos"] },
        accounts: { route: ["List", "Restaurant Order"] },
        "new-account": { route: ["restaurant-pos"] },
        kitchen: { route: ["restaurant-kds"] },
        waiters: { route: ["List", "Employee"], filters: { designation: "Mesero", status: ["in", ["Active", "Inactive", "Suspended", "Left"]] } },
        locations: { route: ["restaurant-location"] },
        tickets: { route: ["restaurant-commands"] },
        tables: { route: ["List", "Restaurant Table"] },
        "table-map": { route: ["restaurant-table-map"] },
        items: { route: ["List", "Item"] },
        groups: { route: ["Tree", "Item Group"] },
        prices: { route: ["List", "Item Price"] },
        "preparation-stages": { route: ["List", "Restaurant Preparation Stage"] },
        "payment-methods": { route: ["List", "Mode of Payment"] },
        customers: { route: ["List", "Customer"] },
        branches: { route: ["List", "Branch"] },
        "price-lists": { route: ["List", "Price List"] },
        uoms: { route: ["List", "UOM"] },
        "sales-analytics": { route: ["query-report", "Sales Analytics"] },
        "sales-register": { route: ["query-report", "Sales Register"] },
        "item-sales": { route: ["query-report", "Item-wise Sales Register"] },
        settings: { route: ["Form", "Restaurant Settings"] },
    };

    async function openRoute(action, extraRouteOptions = null) {
        if (action === "welcome") {
            window.location.assign("/restaurant-welcome");
            return;
        }
        const destination = routes[action];
        if (!destination) return;
        try { await ensureTheme(); }
        catch (error) { /* A visual failure must never block native catalog navigation. */ }
        frappe.restaurant_item_navigation = action === "items";
        frappe.restaurant_theme?.enter(destination.route);
        frappe.route_options = extraRouteOptions ? { ...extraRouteOptions } : (destination.filters ? { ...destination.filters } : null);
        frappe.set_route(...destination.route);
    }

    async function openRestaurantPosConfigDialog(selectedProfile = null) {
        let configData = null;
        try {
            const resp = await frappe.call({
                method: "restaurant.pos.get_restaurant_pos_config",
                args: { pos_profile: selectedProfile }
            });
            configData = resp && resp.message ? resp.message : null;
        } catch (err) {
            frappe.msgprint({ title: "Error", indicator: "red", message: "No se pudo cargar la configuración del Punto de Venta: " + (err.message || err) });
            return;
        }

        if (!configData) {
            frappe.msgprint({ title: "Aviso", indicator: "orange", message: "No se encontró ningún Perfil de Punto de Venta activo." });
            return;
        }

        const data = configData;
        const curProfile = data.selected_profile;

        // Clone dynamic state for payments and presets chips
        let currentPayments = (data.payments || []).map(p => (typeof p === "string" ? p : p.mode_of_payment)).filter(Boolean);
        let currentPresets = [...(data.enabled_presets || [])];

        const dialog = new frappe.ui.Dialog({
            title: "Configuración del Punto de Venta",
            size: "large",
            fields: [{ fieldname: "config_html", fieldtype: "HTML" }]
        });

        // Apply dark Odoo-style palette container with LEAF Green & Blue accents
        const wrapper = dialog.fields_dict.config_html.$wrapper[0];
        wrapper.innerHTML = `
            <style>
                .odoo-cfg-root {
                    background: #1e2430;
                    color: #e2e8f0;
                    font-family: inherit;
                    border-radius: 8px;
                    overflow: hidden;
                    margin: -15px;
                    padding: 0 0 16px 0;
                    font-size: 13px;
                }
                .odoo-cfg-header {
                    background: #171d26;
                    padding: 14px 20px;
                    display: flex;
                    align-items: center;
                    justify-content: space-between;
                    flex-wrap: wrap;
                    gap: 12px;
                    border-bottom: 1px solid #2d3748;
                }
                .odoo-cfg-header-left {
                    display: flex;
                    align-items: center;
                    gap: 12px;
                }
                .odoo-cfg-header-title {
                    font-size: 15px;
                    font-weight: 700;
                    color: #fff;
                    letter-spacing: -.2px;
                }
                .odoo-cfg-profile-select {
                    background: #283344;
                    color: #fff;
                    border: 1px solid #4a5568;
                    border-radius: 6px;
                    padding: 5px 12px;
                    font-weight: 600;
                    font-size: 13.5px;
                    outline: none;
                    cursor: pointer;
                }
                .odoo-cfg-new-store-btn {
                    color: #38bdf8;
                    background: transparent;
                    border: none;
                    font-weight: 600;
                    cursor: pointer;
                    display: flex;
                    align-items: center;
                    gap: 4px;
                    font-size: 13px;
                    padding: 4px 6px;
                    border-radius: 4px;
                    transition: background .15s;
                }
                .odoo-cfg-new-store-btn:hover {
                    background: rgba(56, 189, 248, 0.12);
                    text-decoration: underline;
                }
                .odoo-cfg-save-btn {
                    background: #2F8500;
                    color: #fff;
                    border: none;
                    border-radius: 6px;
                    font-weight: 700;
                    font-size: 13px;
                    padding: 7px 18px;
                    cursor: pointer;
                    transition: background .15s ease;
                }
                .odoo-cfg-save-btn:hover {
                    background: #39a300;
                }
                .odoo-cfg-alert-banner {
                    background: #78350f;
                    border-left: 4px solid #f59e0b;
                    color: #fef3c7;
                    padding: 10px 18px;
                    font-size: 12.5px;
                    line-height: 1.4;
                    display: flex;
                    align-items: center;
                    justify-content: space-between;
                    gap: 10px;
                }
                .odoo-cfg-alert-banner a {
                    color: #38bdf8;
                    text-decoration: underline;
                    font-weight: 600;
                    cursor: pointer;
                }
                .odoo-cfg-body {
                    padding: 16px 20px;
                    max-height: 72vh;
                    overflow-y: auto;
                }
                .odoo-cfg-section {
                    margin-bottom: 22px;
                    border-bottom: 1px solid #2d3748;
                    padding-bottom: 20px;
                }
                .odoo-cfg-section:last-child {
                    border-bottom: none;
                    margin-bottom: 0;
                    padding-bottom: 0;
                }
                .odoo-cfg-section-title {
                    font-size: 14.5px;
                    font-weight: 700;
                    color: #f1f5f9;
                    margin: 0 0 14px 0;
                    display: flex;
                    align-items: center;
                    gap: 8px;
                }
                .odoo-cfg-grid-2 {
                    display: grid;
                    grid-template-columns: 1fr 1fr;
                    gap: 24px;
                }
                @media (max-width: 768px) {
                    .odoo-cfg-grid-2 {
                        grid-template-columns: 1fr;
                        gap: 16px;
                    }
                }
                .odoo-cfg-field-block {
                    display: flex;
                    flex-direction: column;
                    gap: 6px;
                    margin-bottom: 14px;
                }
                .odoo-cfg-checkbox-row {
                    display: flex;
                    align-items: flex-start;
                    gap: 10px;
                    cursor: pointer;
                    user-select: none;
                }
                .odoo-cfg-checkbox-row input[type="checkbox"] {
                    width: 17px;
                    height: 17px;
                    accent-color: #2F8500;
                    margin-top: 2px;
                    cursor: pointer;
                }
                .odoo-cfg-label-main {
                    font-weight: 600;
                    color: #f8fafc;
                    display: flex;
                    align-items: center;
                    gap: 6px;
                }
                .odoo-cfg-subtext {
                    font-size: 12px;
                    color: #94a3b8;
                    line-height: 1.4;
                    margin-top: 2px;
                }
                .odoo-cfg-info-icon {
                    display: inline-flex;
                    align-items: center;
                    justify-content: center;
                    width: 14px;
                    height: 14px;
                    border-radius: 50%;
                    background: #334155;
                    color: #94a3b8;
                    font-size: 10px;
                    cursor: help;
                }
                .odoo-cfg-link {
                    color: #38bdf8;
                    text-decoration: none;
                    font-size: 12px;
                    font-weight: 600;
                    cursor: pointer;
                    display: inline-flex;
                    align-items: center;
                    gap: 4px;
                    margin-top: 4px;
                }
                .odoo-cfg-link:hover {
                    text-decoration: underline;
                    color: #7dd3fc;
                }
                .odoo-chips-container {
                    display: flex;
                    flex-wrap: wrap;
                    gap: 6px;
                    align-items: center;
                    margin: 6px 0;
                }
                .odoo-chip {
                    display: inline-flex;
                    align-items: center;
                    gap: 6px;
                    padding: 3px 10px;
                    border-radius: 14px;
                    font-size: 12px;
                    font-weight: 600;
                    background: #283344;
                    color: #e2e8f0;
                    border: 1px solid #475569;
                }
                .odoo-chip-primary {
                    background: rgba(2, 132, 199, 0.2);
                    color: #38bdf8;
                    border-color: rgba(56, 189, 248, 0.4);
                }
                .odoo-chip-remove {
                    background: none;
                    border: none;
                    color: inherit;
                    opacity: 0.7;
                    cursor: pointer;
                    font-size: 13px;
                    padding: 0;
                    line-height: 1;
                }
                .odoo-chip-remove:hover {
                    opacity: 1;
                    color: #f87171;
                }
                .odoo-cfg-inline-select {
                    background: #283344;
                    color: #e2e8f0;
                    border: 1px solid #475569;
                    border-radius: 6px;
                    padding: 4px 8px;
                    font-size: 12.5px;
                    outline: none;
                }
                .odoo-cfg-radio-row {
                    display: flex;
                    align-items: center;
                    gap: 16px;
                    margin-top: 6px;
                }
                .odoo-cfg-radio-item {
                    display: flex;
                    align-items: center;
                    gap: 6px;
                    cursor: pointer;
                    font-weight: 500;
                    color: #cbd5e1;
                }
                .odoo-cfg-radio-item input[type="radio"] {
                    accent-color: #2F8500;
                    cursor: pointer;
                }
                .odoo-cfg-catalogs-row {
                    display: flex;
                    flex-wrap: wrap;
                    gap: 8px;
                    margin-top: 10px;
                }
                .odoo-cfg-catalog-btn {
                    background: #283344;
                    color: #e2e8f0;
                    border: 1px solid #475569;
                    border-radius: 6px;
                    padding: 6px 14px;
                    font-size: 12.5px;
                    font-weight: 500;
                    cursor: pointer;
                    transition: background .15s, border-color .15s;
                }
                .odoo-cfg-catalog-btn:hover {
                    background: #334155;
                    border-color: #64748b;
                    color: #fff;
                }
            </style>

            <div class="odoo-cfg-root">
                <!-- Top Bar -->
                <div class="odoo-cfg-header">
                    <div class="odoo-cfg-header-left">
                        <span class="odoo-cfg-header-title">Punto de venta</span>
                        <select class="odoo-cfg-profile-select" data-cfg-profile-select>
                            ${data.pos_profiles.map(p => `<option value="${frappe.utils.escape_html(p)}" ${p === curProfile ? "selected" : ""}>${frappe.utils.escape_html(p)}</option>`).join("")}
                        </select>
                        <button type="button" class="odoo-cfg-new-store-btn" data-cfg-new-profile title="Crear un nuevo Perfil de Punto de Venta en LEAF / ERPNext">
                            + Nueva tienda / Perfil PdV
                        </button>
                    </div>
                    <div>
                        <button type="button" class="odoo-cfg-save-btn" data-cfg-main-save>
                            Guardar cambios
                        </button>
                    </div>
                </div>

                <!-- Shift Alert Banner -->
                ${data.has_active_shift ? `
                    <div class="odoo-cfg-alert-banner">
                        <div>
                            <strong>Hay una sesión abierta para este PdV</strong> (${frappe.utils.escape_html(data.active_shift?.user || "")} - ${frappe.utils.escape_html(data.active_shift?.name || "")}).
                            Antes de cambiar algunos ajustes debe cerrar la sesión.
                        </div>
                        <a data-cfg-open-shift>Haga clic aquí para cerrar la sesión</a>
                    </div>
                ` : ""}

                <div class="odoo-cfg-body">
                    <!-- SECTION 1: PUNTO DE VENTA -->
                    <div class="odoo-cfg-section">
                        <div class="odoo-cfg-section-title">Punto de venta</div>
                        <div class="odoo-cfg-grid-2">
                            <!-- Col 1 -->
                            <div>
                                <div class="odoo-cfg-field-block">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="is_bar_restaurant" ${data.is_bar_restaurant ? "checked" : ""}>
                                        <div>
                                            <div class="odoo-cfg-label-main">Es un bar/restaurante</div>
                                        </div>
                                    </label>
                                </div>

                                <div class="odoo-cfg-field-block" style="padding-left: 27px; margin-top: 8px;">
                                    <div class="odoo-cfg-label-main">
                                        Mapa de pisos y mesas
                                        <span class="odoo-cfg-info-icon" title="Diseñe pisos y asigne órdenes a las mesas nativas de restaurante">?</span>
                                    </div>
                                    <div class="odoo-cfg-subtext">Diseñe pisos y asigne órdenes a las mesas</div>
                                    <div style="margin-top: 6px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
                                        <span style="font-size: 12px; color: #94a3b8;">Pisos</span>
                                        <div class="odoo-chips-container" style="margin: 0;">
                                            ${(data.areas || []).map(a => `
                                                <span class="odoo-chip">${frappe.utils.escape_html(a.area_name || a.name)}</span>
                                            `).join("")}
                                        </div>
                                    </div>
                                    <a class="odoo-cfg-link" data-cfg-link="locations">→ Pisos</a>
                                </div>
                            </div>

                            <!-- Col 2 -->
                            <div>
                                <div class="odoo-cfg-field-block">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="para_llevar_entrega" checked>
                                        <div>
                                            <div class="odoo-cfg-label-main">Para llevar / Entrega / Miembros</div>
                                        </div>
                                    </label>
                                    <div class="odoo-cfg-subtext" style="padding-left: 27px;">
                                        Define los valores preestablecidos para gestionar los impuestos y los precios para consumir en el local, para llevar, para miembros y más...
                                    </div>
                                </div>

                                <div class="odoo-cfg-field-block" style="padding-left: 27px;">
                                    <div style="font-size: 12px; color: #94a3b8; font-weight: 600;">Disponible</div>
                                    <div class="odoo-chips-container" data-cfg-presets-container>
                                        <!-- Rendered dynamically -->
                                    </div>
                                    <div style="margin-top: 4px;">
                                        <select class="odoo-cfg-inline-select" data-cfg-add-preset-select>
                                            <option value="">+ Agregar preestablecido...</option>
                                            ${(data.presets || []).map(p => `<option value="${frappe.utils.escape_html(p.preset_name)}">${frappe.utils.escape_html(p.preset_name)}</option>`).join("")}
                                        </select>
                                    </div>

                                    <div style="margin-top: 10px; display: flex; align-items: center; gap: 8px;">
                                        <span style="font-size: 12px; color: #94a3b8; font-weight: 600;">Predeterminado:</span>
                                        <select class="odoo-cfg-inline-select" data-cfg-default-preset-select></select>
                                    </div>
                                    <a class="odoo-cfg-link" data-cfg-link="presets">→ Configurar valores preestablecidos</a>
                                </div>
                            </div>
                        </div>
                    </div>

                    <!-- SECTION 2: PAGO -->
                    <div class="odoo-cfg-section">
                        <div class="odoo-cfg-section-title">Pago</div>
                        <div class="odoo-cfg-grid-2">
                            <!-- Col 1 -->
                            <div>
                                <div class="odoo-cfg-field-block">
                                    <div class="odoo-cfg-label-main">
                                        Métodos de pago
                                        <span class="odoo-cfg-info-icon" title="Métodos de pago disponibles para este Punto de Venta">?</span>
                                    </div>
                                    <div class="odoo-cfg-subtext">Métodos de pago disponibles</div>
                                    <div class="odoo-chips-container" data-cfg-payments-container>
                                        <!-- Rendered dynamically -->
                                    </div>
                                    <div>
                                        <select class="odoo-cfg-inline-select" data-cfg-add-payment-select>
                                            <option value="">+ Agregar método de pago...</option>
                                            ${(data.all_payment_methods || []).map(m => `<option value="${frappe.utils.escape_html(m)}">${frappe.utils.escape_html(m)}</option>`).join("")}
                                        </select>
                                    </div>
                                    <a class="odoo-cfg-link" data-cfg-link="payment-methods">→ Métodos de pago</a>
                                </div>

                                <div class="odoo-cfg-field-block" style="margin-top: 12px;">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="enable_rounded_total" ${data.enable_rounded_total ? "checked" : ""}>
                                        <div>
                                            <div class="odoo-cfg-label-main">
                                                Redondeo total
                                                <span class="odoo-cfg-info-icon" title="Aplica redondeo al total de la venta en efectivo según la denominación">?</span>
                                            </div>
                                            <div class="odoo-cfg-subtext">Define la moneda más pequeña utilizada para pagar en efectivo</div>
                                        </div>
                                    </label>
                                </div>

                                <div class="odoo-cfg-field-block">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="max_difference_enabled" ${data.max_difference_enabled ? "checked" : ""}>
                                        <div>
                                            <div class="odoo-cfg-label-main">Establecer la diferencia máxima</div>
                                            <div class="odoo-cfg-subtext">Defina la diferencia máxima permitida entre el dinero esperado y el dinero contado al cierre de la sesión</div>
                                        </div>
                                    </label>
                                    <div data-cfg-write-off-box style="padding-left: 27px; margin-top: 6px; ${data.max_difference_enabled ? "" : "display:none;"}">
                                        <div style="display: flex; align-items: center; gap: 8px;">
                                            <span style="font-size: 12px; color: #94a3b8;">Límite (${frappe.utils.escape_html(data.currency)}):</span>
                                            <input type="number" min="0" step="0.5" value="${data.write_off_limit || 0}" data-cfg-key="write_off_limit" class="odoo-cfg-inline-select" style="width: 100px;">
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <!-- Col 2 -->
                            <div>
                                <div class="odoo-cfg-field-block">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="auto_validate_orders" ${data.auto_validate_orders ? "checked" : ""}>
                                        <div>
                                            <div class="odoo-cfg-label-main">Validar órdenes de forma automática</div>
                                            <div class="odoo-cfg-subtext">Valide las órdenes pagadas con una terminal de pago en automático</div>
                                        </div>
                                    </label>
                                </div>

                                <div class="odoo-cfg-field-block">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="one_click_pay" ${data.one_click_pay ? "checked" : ""}>
                                        <div>
                                            <div class="odoo-cfg-label-main">Pago con un clic</div>
                                            <div class="odoo-cfg-subtext">Acceso directo para omitir la pantalla de pago</div>
                                        </div>
                                    </label>
                                </div>

                                <div class="odoo-cfg-field-block">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="tips_enabled" ${data.tips_enabled ? "checked" : ""}>
                                        <div>
                                            <div class="odoo-cfg-label-main">
                                                Propinas
                                                <span class="odoo-cfg-info-icon" title="Gestiona propinas voluntarias o servicio sugerido">?</span>
                                            </div>
                                            <div class="odoo-cfg-subtext">Acepte propinas de los clientes o convierta el cambio en propina</div>
                                        </div>
                                    </label>
                                    <div style="padding-left: 27px; margin-top: 6px;">
                                        <label class="odoo-cfg-checkbox-row">
                                            <input type="checkbox" data-cfg-key="tip_after_payment" ${data.tip_after_payment ? "checked" : ""}>
                                            <span style="font-size: 12.5px; color: #cbd5e1;">Agregar propina después del pago</span>
                                        </label>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <!-- SECTION 3: INTERFAZ DE PDV -->
                    <div class="odoo-cfg-section">
                        <div class="odoo-cfg-section-title">Interfaz de PdV</div>
                        <div class="odoo-cfg-grid-2">
                            <!-- Col 1 -->
                            <div>
                                <div class="odoo-cfg-field-block">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="employee_login_required" ${data.employee_login_required ? "checked" : ""}>
                                        <div>
                                            <div class="odoo-cfg-label-main">
                                                Iniciar sesión como empleado
                                                <span class="odoo-cfg-info-icon" title="Permite control de cajeros y meseros mediante código o selección rápida">?</span>
                                            </div>
                                            <div class="odoo-cfg-subtext">Permitir registrar y cambiar entre empleados seleccionados</div>
                                        </div>
                                    </label>
                                </div>

                                <div class="odoo-cfg-field-block">
                                    <div class="odoo-cfg-label-main">Ocultar imágenes en el PdV</div>
                                    <div class="odoo-cfg-subtext">Las interfaces de autopedido no se verán afectadas.</div>
                                    <div style="padding-left: 6px; margin-top: 6px; display: flex; flex-direction: column; gap: 6px;">
                                        <label class="odoo-cfg-checkbox-row">
                                            <input type="checkbox" data-cfg-key="show_product_images" ${data.show_product_images ? "checked" : ""}>
                                            <span style="font-size: 12.5px; color: #cbd5e1;">Mostrar imágenes del producto</span>
                                        </label>
                                        <label class="odoo-cfg-checkbox-row">
                                            <input type="checkbox" data-cfg-key="show_category_images" ${data.show_category_images ? "checked" : ""}>
                                            <span style="font-size: 12.5px; color: #cbd5e1;">Mostrar imágenes de la categoría</span>
                                        </label>
                                    </div>
                                </div>

                                <div class="odoo-cfg-field-block">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="group_by_category" ${data.group_by_category ? "checked" : ""}>
                                        <div>
                                            <div class="odoo-cfg-label-main">Agrupar productos por categorías</div>
                                            <div class="odoo-cfg-subtext">Muestra los productos agrupados por categorías.</div>
                                        </div>
                                    </label>
                                </div>
                            </div>

                            <!-- Col 2 -->
                            <div>
                                <div class="odoo-cfg-field-block">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="large_scrollbars" ${data.large_scrollbars ? "checked" : ""}>
                                        <div>
                                            <div class="odoo-cfg-label-main">Barras de desplazamiento grandes</div>
                                            <div class="odoo-cfg-subtext">Mejore la navegación en pantallas táctiles industriales imprecisas</div>
                                        </div>
                                    </label>
                                </div>

                                <div class="odoo-cfg-field-block">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="online_reservation" ${data.online_reservation ? "checked" : ""}>
                                        <div>
                                            <div class="odoo-cfg-label-main">Reservación</div>
                                            <div class="odoo-cfg-subtext">Reservación en línea para el punto de venta</div>
                                        </div>
                                    </label>
                                </div>

                                <div class="odoo-cfg-field-block">
                                    <div class="odoo-cfg-label-main">Pantalla predeterminada</div>
                                    <div class="odoo-cfg-subtext">Seleccione la mesa primero o después de registrar la orden</div>
                                    <div class="odoo-cfg-radio-row">
                                        <label class="odoo-cfg-radio-item">
                                            <input type="radio" name="rpos_default_screen" value="Mesas" ${data.default_screen === "Mesas" ? "checked" : ""}>
                                            <span>Mesas</span>
                                        </label>
                                        <label class="odoo-cfg-radio-item">
                                            <input type="radio" name="rpos_default_screen" value="Caja" ${data.default_screen !== "Mesas" ? "checked" : ""}>
                                            <span>Caja</span>
                                        </label>
                                    </div>
                                </div>

                                <div class="odoo-cfg-field-block" style="background: rgba(47,133,0,0.08); border: 1px solid rgba(47,133,0,0.25); border-radius: 8px; padding: 12px 14px; margin-top: 10px;">
                                    <label class="odoo-cfg-checkbox-row">
                                        <input type="checkbox" data-cfg-key="idle_wallpaper_enabled" ${data.idle_wallpaper_enabled ? "checked" : ""}>
                                        <div>
                                            <div class="odoo-cfg-label-main" style="color: #86efac;">
                                                Wallpaper / Protector de pantalla por inactividad
                                            </div>
                                            <div class="odoo-cfg-subtext" style="color: #cbd5e1;">
                                                Activa pantalla de reposo con tu fondo y logo de empresa centrado tras el tiempo configurado sin manipulación.
                                            </div>
                                        </div>
                                    </label>

                                    <div style="display: flex; align-items: center; gap: 8px; margin-top: 10px; padding-left: 27px;">
                                        <span style="font-size: 12px; color: #94a3b8;">Tiempo de inactividad:</span>
                                        <select class="odoo-cfg-inline-select" data-cfg-idle-preset-select>
                                            <option value="0.5">0.5 minutos (30 seg)</option>
                                            <option value="1">1 minuto (60 s)</option>
                                            <option value="2">2 minutos (120 s)</option>
                                            <option value="3">3 minutos (180 s)</option>
                                            <option value="5">5 minutos (300 s)</option>
                                            <option value="10">10 minutos (600 s)</option>
                                            <option value="15">15 minutos (900 s)</option>
                                            <option value="custom">Personalizado</option>
                                        </select>
                                        <input type="number" min="0.5" max="180" step="0.5" value="${((data.idle_wallpaper_timeout || 120) / 60).toFixed(1)}" data-cfg-key="idle_wallpaper_minutes" class="odoo-cfg-inline-select" style="width: 80px; font-weight: 700;">
                                        <span style="font-size: 12px; color: #94a3b8;">minuto(s)</span>
                                    </div>

                                    <div style="margin-top: 10px; padding-left: 27px;">
                                        <div style="font-size: 12px; color: #94a3b8; margin-bottom: 4px;">Fondo del Wallpaper:</div>
                                        <div style="display: flex; gap: 8px; align-items: center;">
                                            <input type="text" data-cfg-key="idle_wallpaper_bg" value="${data.idle_wallpaper_background_url || '/assets/restaurant/images/background-light.svg'}" placeholder="/assets/restaurant/images/background-light.svg" class="odoo-cfg-inline-select" style="flex: 1; min-width: 0; font-size: 12px;">
                                            <button type="button" class="odoo-cfg-catalog-btn" data-cfg-upload-bg style="white-space: nowrap; font-size: 12px; padding: 4px 10px; background: #283344; color: #38bdf8; border: 1px solid #4a5568;">
                                                📁 Subir fondo
                                            </button>
                                        </div>
                                    </div>

                                    <div style="margin-top: 10px; padding-left: 27px;">
                                        <div style="font-size: 12px; color: #94a3b8; margin-bottom: 4px;">Logotipo de la Empresa (Centrado):</div>
                                        <div style="display: flex; gap: 8px; align-items: center;">
                                            <input type="text" data-cfg-key="idle_wallpaper_logo" value="${data.idle_wallpaper_logo_url || ''}" placeholder="URL o archivo del logotipo corporativo" class="odoo-cfg-inline-select" style="flex: 1; min-width: 0; font-size: 12px;">
                                            <button type="button" class="odoo-cfg-catalog-btn" data-cfg-upload-logo style="white-space: nowrap; font-size: 12px; padding: 4px 10px; background: #283344; color: #38bdf8; border: 1px solid #4a5568;">
                                                🏢 Subir logo
                                            </button>
                                        </div>
                                    </div>

                                    <div style="margin-top: 10px; padding-left: 27px;">
                                        <label class="odoo-cfg-checkbox-row" style="margin: 0; align-items: center; cursor: pointer;">
                                            <input type="checkbox" data-cfg-key="idle_wallpaper_show_clock" ${data.idle_wallpaper_show_clock !== 0 ? "checked" : ""}>
                                            <div>
                                                <div class="odoo-cfg-label-main" style="color: #cbd5e1; font-size: 13px;">
                                                    Mostrar hora y fecha en vivo
                                                </div>
                                                <div class="odoo-cfg-subtext" style="color: #94a3b8; font-size: 11.5px;">
                                                    Muestra en la parte superior el reloj contando segundos y la fecha completa (día y mes).
                                                </div>
                                            </div>
                                        </label>
                                    </div>

                                    <div style="margin-top: 12px; padding-left: 27px;">
                                        <div style="font-size: 12px; color: #94a3b8; margin-bottom: 4px;">Vista previa del Wallpaper:</div>
                                        <div data-cfg-wp-preview style="height: 110px; border-radius: 6px; border: 1px solid #4a5568; background-size: cover; background-position: center; display: flex; align-items: center; justify-content: center; position: relative; overflow: hidden; background-color: #171d26;">
                                            <img data-cfg-wp-preview-logo src="" alt="Logo" style="max-height: 50px; max-width: 140px; object-fit: contain; filter: drop-shadow(0 2px 8px rgba(0,0,0,0.4)); display: none;">
                                            <span data-cfg-wp-preview-placeholder style="font-size: 13px; font-weight: 700; color: #94a3b8;">LEAF RESTAURANT</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <!-- SECTION 4: CATALOGOS ADICIONALES -->
                    <div class="odoo-cfg-section">
                        <div class="odoo-cfg-section-title" style="font-size: 13.5px; color: #94a3b8;">
                            Catálogos adicionales de LEAF Restaurant
                        </div>
                        <div class="odoo-cfg-catalogs-row">
                            <button type="button" class="odoo-cfg-catalog-btn" data-cfg-catalog="branches">Sucursales</button>
                            <button type="button" class="odoo-cfg-catalog-btn" data-cfg-catalog="price-lists">Listas de precios</button>
                            <button type="button" class="odoo-cfg-catalog-btn" data-cfg-catalog="uoms">Unidades de medida</button>
                            <button type="button" class="odoo-cfg-catalog-btn" data-cfg-catalog="welcome">Página de bienvenida</button>
                            <button type="button" class="odoo-cfg-catalog-btn" data-cfg-catalog="pos" style="background:#2F8500; border-color:#236600; color:#fff; font-weight:700;">Ir al Punto de Venta</button>
                        </div>
                    </div>
                </div>
            </div>
        `;

        // Interactive logic for Chips & Dropdowns
        const presetsCont = wrapper.querySelector("[data-cfg-presets-container]");
        const defaultPresetSel = wrapper.querySelector("[data-cfg-default-preset-select]");
        const addPresetSel = wrapper.querySelector("[data-cfg-add-preset-select]");

        function renderPresets() {
            presetsCont.innerHTML = currentPresets.map((name, idx) => `
                <span class="odoo-chip ${idx === 0 ? "odoo-chip-primary" : ""}">
                    ${frappe.utils.escape_html(name)}
                    <button type="button" class="odoo-chip-remove" data-remove-preset="${frappe.utils.escape_html(name)}">×</button>
                </span>
            `).join("");

            // Re-render default preset dropdown
            const curDef = data.default_preset || currentPresets[0] || "Comer en el local";
            defaultPresetSel.innerHTML = currentPresets.map(name => `
                <option value="${frappe.utils.escape_html(name)}" ${name === curDef ? "selected" : ""}>${frappe.utils.escape_html(name)}</option>
            `).join("");

            presetsCont.querySelectorAll("[data-remove-preset]").forEach(btn => {
                btn.addEventListener("click", () => {
                    const target = btn.dataset.removePreset;
                    currentPresets = currentPresets.filter(p => p !== target);
                    renderPresets();
                });
            });
        }
        renderPresets();

        addPresetSel.addEventListener("change", () => {
            const val = addPresetSel.value;
            if (val && !currentPresets.includes(val)) {
                currentPresets.push(val);
                renderPresets();
            }
            addPresetSel.value = "";
        });

        // Payment Chips logic
        const paymentsCont = wrapper.querySelector("[data-cfg-payments-container]");
        const addPaymentSel = wrapper.querySelector("[data-cfg-add-payment-select]");

        function renderPayments() {
            paymentsCont.innerHTML = currentPayments.map(name => `
                <span class="odoo-chip">
                    ${frappe.utils.escape_html(name)}
                    <button type="button" class="odoo-chip-remove" data-remove-payment="${frappe.utils.escape_html(name)}">×</button>
                </span>
            `).join("");

            paymentsCont.querySelectorAll("[data-remove-payment]").forEach(btn => {
                btn.addEventListener("click", () => {
                    const target = btn.dataset.removePayment;
                    currentPayments = currentPayments.filter(m => m !== target);
                    renderPayments();
                });
            });
        }
        renderPayments();

        addPaymentSel.addEventListener("change", () => {
            const val = addPaymentSel.value;
            if (val && !currentPayments.includes(val)) {
                currentPayments.push(val);
                renderPayments();
            }
            addPaymentSel.value = "";
        });

        // Toggle write-off box
        const maxDiffChk = wrapper.querySelector('[data-cfg-key="max_difference_enabled"]');
        const writeOffBox = wrapper.querySelector("[data-cfg-write-off-box]");
        maxDiffChk.addEventListener("change", () => {
            writeOffBox.style.display = maxDiffChk.checked ? "block" : "none";
        });

        // Wallpaper preset time syncing
        const idlePresetSel = wrapper.querySelector("[data-cfg-idle-preset-select]");
        const idleMinInp = wrapper.querySelector('[data-cfg-key="idle_wallpaper_minutes"]');
        const syncIdleSelect = (minVal) => {
            const strVal = String(parseFloat(minVal || 2));
            const hasOpt = [...idlePresetSel.options].some(o => o.value === strVal);
            idlePresetSel.value = hasOpt ? strVal : "custom";
        };
        syncIdleSelect(idleMinInp.value);
        idlePresetSel.addEventListener("change", () => {
            if (idlePresetSel.value !== "custom") {
                idleMinInp.value = idlePresetSel.value;
            }
        });
        idleMinInp.addEventListener("input", () => syncIdleSelect(idleMinInp.value));

        // Wallpaper uploads & live preview
        const bgInput = wrapper.querySelector('[data-cfg-key="idle_wallpaper_bg"]');
        const logoInput = wrapper.querySelector('[data-cfg-key="idle_wallpaper_logo"]');
        const previewBox = wrapper.querySelector("[data-cfg-wp-preview]");
        const previewLogo = wrapper.querySelector("[data-cfg-wp-preview-logo]");
        const previewPlaceholder = wrapper.querySelector("[data-cfg-wp-preview-placeholder]");

        const updateWpPreview = () => {
            const bg = bgInput?.value?.trim() || "";
            const logo = logoInput?.value?.trim() || "";
            if (previewBox) {
                if (bg) {
                    previewBox.style.backgroundImage = `url("${bg}")`;
                } else {
                    previewBox.style.backgroundImage = "none";
                    previewBox.style.backgroundColor = "#171d26";
                }
            }
            if (previewLogo && previewPlaceholder) {
                if (logo) {
                    previewLogo.src = logo;
                    previewLogo.style.display = "block";
                    previewPlaceholder.style.display = "none";
                } else {
                    previewLogo.style.display = "none";
                    previewPlaceholder.style.display = "block";
                }
            }
        };
        updateWpPreview();
        bgInput?.addEventListener("input", updateWpPreview);
        logoInput?.addEventListener("input", updateWpPreview);

        wrapper.querySelector("[data-cfg-upload-bg]")?.addEventListener("click", () => {
            new frappe.ui.FileUploader({
                make_attachments_public: 1,
                on_success: (file_doc) => {
                    if (file_doc && file_doc.file_url && bgInput) {
                        bgInput.value = file_doc.file_url;
                        updateWpPreview();
                    }
                }
            });
        });

        wrapper.querySelector("[data-cfg-upload-logo]")?.addEventListener("click", () => {
            new frappe.ui.FileUploader({
                make_attachments_public: 1,
                on_success: (file_doc) => {
                    if (file_doc && file_doc.file_url && logoInput) {
                        logoInput.value = file_doc.file_url;
                        updateWpPreview();
                    }
                }
            });
        });

        // Switch POS Profile
        const profileSel = wrapper.querySelector("[data-cfg-profile-select]");
        profileSel.addEventListener("change", () => {
            dialog.hide();
            openRestaurantPosConfigDialog(profileSel.value);
        });

        // "+ Nueva tienda / Perfil PdV"
        const newProfBtn = wrapper.querySelector("[data-cfg-new-profile]");
        if (newProfBtn) {
            newProfBtn.addEventListener("click", () => {
                dialog.hide();
                frappe.set_route("Form", "POS Profile", "new-pos-profile-1");
            });
        }

        // Active shift link
        const openShiftLnk = wrapper.querySelector("[data-cfg-open-shift]");
        if (openShiftLnk) {
            openShiftLnk.addEventListener("click", () => {
                dialog.hide();
                if (data.active_shift?.name) {
                    frappe.set_route("Form", "POS Opening Shift", data.active_shift.name);
                } else {
                    frappe.set_route("List", "POS Opening Shift");
                }
            });
        }

        // Links
        wrapper.querySelectorAll("[data-cfg-link]").forEach(lnk => {
            lnk.addEventListener("click", (e) => {
                e.preventDefault();
                const target = lnk.dataset.cfgLink;
                dialog.hide();
                if (target === "locations") openRoute("locations");
                else if (target === "presets") frappe.set_route("List", "Restaurant Order Preset");
                else if (target === "payment-methods") openRoute("payment-methods");
            });
        });

        // Catalogs
        wrapper.querySelectorAll("[data-cfg-catalog]").forEach(btn => {
            btn.addEventListener("click", () => {
                const act = btn.dataset.cfgCatalog;
                dialog.hide();
                openRoute(act);
            });
        });

        // Save button handler
        const saveBtn = wrapper.querySelector("[data-cfg-main-save]");
        saveBtn.addEventListener("click", async () => {
            saveBtn.disabled = true;
            saveBtn.textContent = "Guardando...";

            const getChk = (key) => wrapper.querySelector(`[data-cfg-key="${key}"]`)?.checked ? 1 : 0;
            const defaultScreen = wrapper.querySelector('input[name="rpos_default_screen"]:checked')?.value || "Caja";

            const payload = {
                is_bar_restaurant: getChk("is_bar_restaurant"),
                enabled_areas: data.enabled_areas,
                enabled_presets: currentPresets,
                default_preset: defaultPresetSel.value || currentPresets[0] || "Comer en el local",
                payments: currentPayments,
                enable_rounded_total: getChk("enable_rounded_total"),
                max_difference_enabled: getChk("max_difference_enabled"),
                write_off_limit: parseFloat(wrapper.querySelector('[data-cfg-key="write_off_limit"]')?.value || 0),
                auto_validate_orders: getChk("auto_validate_orders"),
                one_click_pay: getChk("one_click_pay"),
                tips_enabled: getChk("tips_enabled"),
                tip_after_payment: getChk("tip_after_payment"),
                employee_login_required: getChk("employee_login_required"),
                show_product_images: getChk("show_product_images"),
                show_category_images: getChk("show_category_images"),
                group_by_category: getChk("group_by_category"),
                large_scrollbars: getChk("large_scrollbars"),
                online_reservation: getChk("online_reservation"),
                default_screen: defaultScreen,
                idle_wallpaper_enabled: getChk("idle_wallpaper_enabled"),
                idle_wallpaper_timeout: Math.max(5, Math.round((parseFloat(idleMinInp.value || 2) * 60))),
                idle_wallpaper_background_url: bgInput?.value?.trim() || "/assets/restaurant/images/background-light.svg",
                idle_wallpaper_logo_url: logoInput?.value?.trim() || "",
                idle_wallpaper_show_clock: getChk("idle_wallpaper_show_clock"),
            };

            try {
                // Update localStorage immediately so POS instance uses it
                try {
                    localStorage.setItem("rpos_idle_wallpaper_config", JSON.stringify({
                        enabled: payload.idle_wallpaper_enabled,
                        timeout_seconds: payload.idle_wallpaper_timeout,
                        background_url: payload.idle_wallpaper_background_url,
                        logo_url: payload.idle_wallpaper_logo_url,
                        show_clock: payload.idle_wallpaper_show_clock
                    }));
                } catch (e) {}

                await frappe.call({
                    method: "restaurant.pos.save_restaurant_pos_config",
                    args: {
                        pos_profile: curProfile,
                        config: payload
                    }
                });

                frappe.show_alert({
                    message: "Configuración del Punto de Venta guardada exitosamente.",
                    indicator: "green"
                });
                dialog.hide();
            } catch (err) {
                frappe.msgprint({
                    title: "Error al guardar",
                    indicator: "red",
                    message: "No se pudieron guardar los cambios: " + (err.message || err)
                });
            } finally {
                saveBtn.disabled = false;
                saveBtn.textContent = "Guardar cambios";
            }
        });

        dialog.show();
    }

    function openReportsDialog() {
        const options = [
            ["sales-analytics", "Análisis de ventas"],
            ["sales-register", "Registro de ventas"],
            ["item-sales", "Ventas por producto"]
        ];
        const content = document.createElement("div");
        content.className = "d-grid";
        content.style.cssText = "display:grid;gap:10px;padding:4px 0";

        const hint = document.createElement("p");
        hint.className = "text-muted";
        hint.style.marginBottom = "2px";
        hint.textContent = "Consulta los reportes nativos de LEAF y selecciona la empresa y el período que deseas analizar.";
        content.appendChild(hint);

        const dialog = new frappe.ui.Dialog({
            title: "Reportes",
            fields: [{ fieldname: "options", fieldtype: "HTML" }],
        });

        options.forEach(([action, label]) => {
            const button = document.createElement("button");
            button.type = "button";
            button.className = "btn btn-default text-left";
            button.style.minHeight = "44px";
            button.textContent = label;
            button.addEventListener("click", () => { dialog.hide(); openRoute(action); });
            content.appendChild(button);
        });

        dialog.fields_dict.options.$wrapper[0].appendChild(content);
        dialog.show();
    }

    const userRoles = Array.isArray(frappe.user_roles) ? frappe.user_roles : [];
    const isAdminOrManager = userRoles.includes("Restaurant Manager") || userRoles.includes("System Manager") || frappe.session.user === "Administrator";
    const isCashierOnly = (userRoles.includes("Restaurant Cashier") || userRoles.includes("Restaurant Direct Cashier")) && !isAdminOrManager;
    const isWaiterOnly = userRoles.includes("Restaurant User") && !isCashierOnly && !isAdminOrManager;
    const waiterAllowedActions = new Set(["pos", "accounts", "table-map", "locations", "tables"]);
    const cashierAllowedActions = new Set(["pos", "accounts", "kitchen", "tickets", "reports", "customers"]);
    const restrictedActions = isCashierOnly ? cashierAllowedActions : (isWaiterOnly ? waiterAllowedActions : null);
    if (restrictedActions) {
        root_element.querySelectorAll(".lr-card[data-action]").forEach((card) => {
            if (!restrictedActions.has(card.dataset.action)) {
                card.style.display = "none";
            }
        });
        root_element.querySelectorAll(".lr-section").forEach((section) => {
            const visibleCards = [...section.querySelectorAll(".lr-card[data-action]")].filter((c) => c.style.display !== "none");
            if (!visibleCards.length) {
                section.style.display = "none";
            }
        });
    }

    root_element.querySelector(".lr-dashboard").addEventListener("click", (event) => {
        const card = event.target.closest("[data-action]");
        if (!card) return;
        const action = card.dataset.action;
        if (restrictedActions && !restrictedActions.has(action)) {
            frappe.msgprint({ title: "Acceso restringido", indicator: "orange", message: "Tu rol actual no tiene acceso a esta opción del módulo." });
            return;
        }
        if (card.dataset.pending === "true") {
            const title = card.querySelector(".lr-card-title").textContent;
            frappe.msgprint({ title, indicator: "blue", message: "Esta opción está en preparación y todavía no está habilitada. Tus datos y cuentas no se han modificado." });
            return;
        }
        if (action === "settings") openRoute("settings");
        else if (action === "reports") openReportsDialog();
        else openRoute(action);
    });
})();

style:
/* Styles stay inside the native Workspace custom block shadow root. */
:host { display: block; }
.lr-dashboard { --lr-blue: #369900; --icon-stroke: currentColor; --icon-fill: transparent; color: #142137; font-family: inherit; -webkit-font-smoothing: antialiased; }
.lr-dashboard *, .lr-dashboard *::before, .lr-dashboard *::after { box-sizing: border-box; }
.lr-intro { margin: 0 0 20px; color: #8693a7; font-size: 13px; line-height: 1.5; }
.lr-panel { padding: 20px; background: #fff; border: 1px solid #dcebd3; border-radius: 12px; box-shadow: 0 2px 12px rgba(25, 45, 75, .025); }
.lr-section + .lr-section { margin-top: 18px; padding-top: 18px; border-top: 1px solid #9dca7c; }
.lr-section-header { display: flex; align-items: center; gap: 14px; margin-bottom: 16px; }
.lr-section-icon { display: flex; flex: 0 0 30px; width: 30px; height: 34px; align-items: center; justify-content: center; color: var(--lr-blue); }
.lr-section-icon-featured { background: #effbe9; border-radius: 8px; }
.lr-section-icon svg { width: 26px; height: 26px; }
.lr-section h2 { margin: 0 0 3px; color: #142137; font-size: 16px; font-weight: 700; line-height: 1.3; letter-spacing: -.2px; }
.lr-section-header p { margin: 0; color: #8693a7; font-size: 12.5px; line-height: 1.4; }
.lr-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.lr-card { position: relative; display: flex; align-items: center; gap: 18px; min-width: 0; min-height: 88px; padding: 13px 14px; text-align: left; color: inherit; background: #fff; border: 1px solid #e4ebf4; border-radius: 7px; box-shadow: none; cursor: pointer; font-family: inherit; transition: border-color .15s ease, background-color .15s ease, box-shadow .15s ease; -webkit-tap-highlight-color: transparent; }
.lr-card:hover { border-color: #a4ce87; background: #fbfef8; box-shadow: 0 3px 10px rgba(47, 133, 0, .06); }
.lr-card:active { background: #effbe9; }
.lr-card:focus-visible { outline: 2px solid var(--lr-blue); outline-offset: 3px; }
.lr-card-icon { display: flex; flex: 0 0 50px; width: 50px; height: 50px; align-items: center; justify-content: center; color: var(--lr-blue); background: #effbe9; border-radius: 11px; }
.lr-card-icon svg { width: 28px; height: 28px; }
.lr-font-icon { font-family: FontAwesome; font-style: normal; font-weight: normal; font-size: 27px; line-height: 1; text-rendering: auto; }
.lr-card-copy { display: block; flex: 1 1 auto; min-width: 0; padding-right: 12px; }
.lr-card-title { display: block; margin-bottom: 4px; color: #142137; font-size: 14px; font-weight: 650; line-height: 1.3; letter-spacing: -.15px; }
.lr-card-description { display: block; color: #8592a7; font-size: 12.5px; font-weight: 400; line-height: 1.4; }
.lr-chevron { position: absolute; display: flex; top: 15px; right: 13px; color: var(--lr-blue); }
.lr-chevron svg { width: 15px; height: 15px; }
@media (max-width: 1000px) { .lr-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 620px) { .lr-grid { grid-template-columns: minmax(0, 1fr); } .lr-panel { padding: 16px; } .lr-card { min-height: 88px; } .lr-section-header { gap: 10px; } }
@media (prefers-reduced-motion: reduce) { .lr-card { transition: none; } }
